CREATE TABLE fin_accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,institution TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN ('asset','liability')),kind TEXT NOT NULL CHECK(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset','credit_card','loan','other_liability')),counted INTEGER NOT NULL CHECK(counted IN (0,1)),opened_on TEXT NOT NULL,closed_on TEXT,notes TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,CHECK((side='asset')=(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset'))),CHECK(closed_on IS NULL OR closed_on>opened_on));
CREATE TABLE fin_snapshots(id TEXT PRIMARY KEY,date TEXT NOT NULL,notes TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE UNIQUE INDEX fin_snapshots_live_date ON fin_snapshots(date) WHERE deleted_at IS NULL;
CREATE TABLE fin_snapshot_entries(snapshot_id TEXT NOT NULL REFERENCES fin_snapshots(id),account_id TEXT NOT NULL REFERENCES fin_accounts(id),state TEXT NOT NULL CHECK(state IN ('entered','unchanged','missing')),amount_cents INTEGER CHECK(amount_cents BETWEEN 0 AND 99999999999),side TEXT NOT NULL CHECK(side IN ('asset','liability')),kind TEXT NOT NULL,counted INTEGER NOT NULL CHECK(counted IN (0,1)),PRIMARY KEY(snapshot_id,account_id),CHECK((state='missing')=(amount_cents IS NULL)),CHECK((side='asset')=(kind IN ('cash','investment','mixed','fund','bond','housing_fund','other_asset'))));
CREATE INDEX fin_entries_account ON fin_snapshot_entries(account_id);
PRAGMA user_version=15;
